import heapq


def k_machine_schedule(jobs: list[list[int]], k: int) -> int:
    if not jobs or k <= 0:
        return 0

    coords = sorted({t for start, end, _ in jobs for t in (start, end)})
    idx = {t: i for i, t in enumerate(coords)}
    m = len(coords)

    adj: list[list[list[int]]] = [[] for _ in range(m)]

    def add_edge(u: int, v: int, cap: int, cost: int) -> None:
        adj[u].append([v, cap, cost, len(adj[v])])
        adj[v].append([u, 0, -cost, len(adj[u]) - 1])

    for i in range(m - 1):
        add_edge(i, i + 1, k, 0)

    for start, end, pay in jobs:
        add_edge(idx[start], idx[end], 1, -pay)

    INF = 10**18
    pot = [INF] * m
    pot[0] = 0
    for u in range(m):
        if pot[u] == INF:
            continue
        for v, cap, cost, _ in adj[u]:
            if cap > 0 and pot[u] + cost < pot[v]:
                pot[v] = pot[u] + cost

    total_cost = 0
    for _ in range(k):
        dist = [INF] * m
        dist[0] = 0
        parent_node = [-1] * m
        parent_edge = [-1] * m
        pq = [(0, 0)]

        while pq:
            d, u = heapq.heappop(pq)
            if d > dist[u]:
                continue
            for i, (v, cap, cost, _) in enumerate(adj[u]):
                if cap > 0:
                    nd = d + cost + pot[u] - pot[v]
                    if nd < dist[v]:
                        dist[v] = nd
                        parent_node[v] = u
                        parent_edge[v] = i
                        heapq.heappush(pq, (nd, v))

        if dist[m - 1] == INF:
            break

        for i in range(m):
            if dist[i] < INF:
                pot[i] += dist[i]

        if pot[m - 1] >= 0:
            break

        cur = m - 1
        while cur != 0:
            p = parent_node[cur]
            e_idx = parent_edge[cur]
            edge = adj[p][e_idx]
            edge[1] -= 1
            adj[cur][edge[3]][1] += 1
            cur = p

        total_cost += pot[m - 1]

    return -total_cost
